        /* Device Mode Extra Data: OEM_DMEXTRA */

        typedef struct {
                uint32 dwSize;
                spoolss_DM_Signature dwSignature;
                uint32 dwVersion;
                [flag(NDR_REMAINING)] DATA_BLOB Data;
        } spoolss_OEM_DMEXTRA;

        typedef [nodiscriminant] union {
